operations.reducer:
if (state.status === "PAID" || state.status === "VOID") throw new InvoiceClosedError("A paid or void invoice cannot change");
const i = action.input;
if (i.direction !== undefined && i.direction !== null) {
  if (state.status !== "DRAFT") throw new InvoiceIssuedError("The direction is fixed once the invoice is issued");
  state.direction = i.direction;
}
if (i.currency !== undefined && i.currency !== null) {
  if (state.status !== "DRAFT") throw new InvoiceIssuedError("The currency is fixed once the invoice is issued");
  state.currency = i.currency;
}
if (i.number !== undefined) state.number = i.number;
if (i.counterpartyName !== undefined) state.counterparty.name = i.counterpartyName;
if (i.contactId !== undefined) state.counterparty.contactId = i.contactId;
if (i.email !== undefined) state.counterparty.email = i.email;
if (i.vatId !== undefined) state.counterparty.vatId = i.vatId;
if (i.address !== undefined) state.counterparty.address = i.address;
if (i.reference !== undefined) state.reference = i.reference;
if (i.notes !== undefined) state.notes = i.notes;
if (i.dueAt !== undefined) state.dueAt = i.dueAt;

if (state.status !== "DRAFT") throw new InvoiceNotDraftError("Lines can only change on a draft");
if (action.input.quantity <= 0) throw new InvalidLineError("Quantity must be positive");
state.lines.push({
  id: action.input.id,
  description: action.input.description,
  quantity: action.input.quantity,
  unitPrice: action.input.unitPrice,
  vatRate: action.input.vatRate,
});

if (state.status !== "DRAFT") throw new InvoiceNotDraftError("Lines can only change on a draft");
const line = state.lines.find((l) => l.id === action.input.id);
if (!line) throw new LineNotFoundError(`Line ${action.input.id} not found`);
if (action.input.quantity !== undefined && action.input.quantity !== null) {
  if (action.input.quantity <= 0) throw new InvalidLineError("Quantity must be positive");
  line.quantity = action.input.quantity;
}
if (action.input.description !== undefined && action.input.description !== null) line.description = action.input.description;
if (action.input.unitPrice !== undefined && action.input.unitPrice !== null) line.unitPrice = action.input.unitPrice;
if (action.input.vatRate !== undefined && action.input.vatRate !== null) line.vatRate = action.input.vatRate;

if (state.status !== "DRAFT") throw new InvoiceNotDraftError("Lines can only change on a draft");
const index = state.lines.findIndex((l) => l.id === action.input.id);
if (index === -1) throw new LineNotFoundError(`Line ${action.input.id} not found`);
state.lines.splice(index, 1);

operations.schema:
input IssueInvoiceInput {
  number: String!
  issuedAt: DateTime!
  dueAt: DateTime!
}

operations.reducer:
if (state.status !== "DRAFT") throw new InvoiceNotDraftError("Only a draft can be issued");
if (state.lines.length === 0) throw new NoLinesError("An invoice needs at least one line");
state.number = action.input.number;
state.issuedAt = action.input.issuedAt;
state.dueAt = action.input.dueAt;
state.status = "OPEN";

if (state.status !== "OPEN") throw new InvoiceNotOpenError("Payments apply to open invoices only");
if (action.input.amount <= 0) throw new InvalidPaymentError("A payment must be positive");
state.payments.push({
  id: action.input.id,
  paidAt: action.input.paidAt,
  amount: action.input.amount,
  method: action.input.method,
  transactionId: action.input.transactionId || null,
});
const total = state.lines.reduce((sum, l) => sum + l.quantity * l.unitPrice * (1 + l.vatRate / 100), 0);
const paid = state.payments.reduce((sum, p) => sum + p.amount, 0);
if (paid >= total - 0.005) state.status = "PAID";

if (state.status === "PAID") throw new InvoicePaidError("A paid invoice cannot be voided");
if (state.status === "VOID") throw new InvoiceVoidError("The invoice is already void");
state.status = "VOID";
state.voidReason = action.input.reason;
